package com.tekwatt.reporting.service;import static org.assertj.core.api.Assertions.assertThat;import com.fasterxml.jackson.databind.ObjectMapper;import com.tekwatt.reporting.entity.ReportType;import java.nio.file.*;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import org.junit.jupiter.api.Test;class PdfReportGeneratorTests{@Test void createsReadableMultiPagePdf()throws Exception{var mapper=new ObjectMapper();var rows=mapper.createArrayNode();for(int i=1;i<=30;i++)rows.addObject().put("date","2026-08-"+String.format("%02d",i)).put("sessions",i).put("energyKwh",i*12.5).put("revenue",i*25);byte[] bytes=new PdfReportGenerator().generate(ReportType.DAILY,rows);Path output=Path.of("target","test-output","sample-report.pdf");Files.createDirectories(output.getParent());Files.write(output,bytes);try(var document=Loader.loadPDF(bytes)){assertThat(document.getNumberOfPages()).isEqualTo(2);assertThat(new PDFTextStripper().getText(document)).contains("TekWatt DAILY Report","2026-08-30");}assertThat(bytes).startsWith('%','P','D','F');}}
